fn is_prime(n: i8) -> bool {
    // Requires that n is within the valid range for prime checking
    // Ensures that the return value is true if n is prime, false otherwise
    // Invariant: n is an i8, and we only check for n >= 2
    // Decreases clause: The loop variable k decreases from n-1 to 2
    // The function is expected to terminate when k reaches 2
    // The function will return false if n < 2 or if a divisor is found

    // Check if n is less than 2, in which case it is not prime
    if n < 2 {
        return false;
    }

    // Iterate over possible divisors from 2 to n-1
    for k in 2..n {
        // If n is divisible by k, it is not prime
        if n % k == 0 {
            return false;
        }
    }

    // If no divisors were found, n is prime
    true
}

fn main() {
    // Test cases
    println!("{}", is_prime(1));  // false
    println!("{}", is_prime(2));  // true
    println!("{}", is_prime(3));  // true
    println!("{}", is_prime(4));  // false
    println!("{}", is_prime(5));  // true
    println!("{}", is_prime(-1)); // false
    println!("{}", is_prime(-5)); // false
    println!("{}", is_prime(127)); // true
    println!("{}", is_prime(128)); // false
}